export function run(mode:number){const k=mode===1?2:1,scores=[[.8,.1,.07,.03],[.05,.1,.8,.05]],routes=scores.map(row=>row.map((score,i)=>({score,i})).sort((a,b)=>b.score-a.score||a.i-b.i).slice(0,k).map(r=>r.i)),union=new Set(routes.flat());return {k,scores,routes,stored:20+100*scores[0].length,active:20+100*routes[0].length,batch:20+100*union.size};}

function Picture({mode}:{mode:number}){const r=m.run(mode);return <svg className={s.plot} viewBox="0 0 280 118" role="img" aria-label="Stored is not switched on \u2014 computed finite mechanism"><text x="6" y="15">A: .8 .1 .07 .03</text><text x="6" y="32">B: .05 .1 .8 .05</text>{[0,1,2,3].map(i=><g key={i}><rect x={9+i*70} y="40" width="58" height="29" className={r.routes[0].includes(i)?s.selected:s.box}/><text x={38+i*70} y="60" textAnchor="middle">E{i+1}</text></g>)}<text x="6" y="91">stored={r.stored} · A active={r.active}</text><text x="6" y="111">B→{r.routes[1].map(i=>'E'+(i+1)).join(',')} · batch={r.batch}</text></svg>;}

Locked inputs: Four experts each hold 100 parameters; router holds 20. A ranks E1 first; B ranks E3 first.
